### Phase 3: Verification & Testing (TASK-006 & TASK-007)

To verify WCAG 2.1 AA compliance (specifically targeting the 4.5:1 brand contrast in dark mode) and theme toggling behavior, we write a comprehensive test suite.

```tsx
/* components/UserSettings/UserSettingsView.test.tsx */
import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { axe, toHaveNoViolations } from 'jest-axe';
import { ThemeProvider } from '../../context/ThemeContext';
import { UserSettingsView } from './UserSettingsView';

expect.extend(toHaveNoViolations);

const renderWithTheme = (ui: React.ReactElement) => {
  return render(<ThemeProvider>{ui}</ThemeProvider>);
};

describe('UserSettingsView - Material 3 & Dark Theme', () => {
  beforeEach(() => {
    localStorage.clear();
    // Mock matchMedia
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: jest.fn().mockImplementation((query) => ({
        matches: false,
        media: query,
        onchange: null,
        addEventListener: jest.fn(),
        removeEventListener: jest.fn(),
        dispatchEvent: jest.fn(),
      })),
    });
  });

  it('should render without accessibility violations in light mode', async () => {
    const { container } = renderWithTheme(<UserSettingsView />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('should render without accessibility violations in dark mode', async () => {
    const { container } = renderWithTheme(<UserSettingsView />);

    // Switch to Dark Mode
    const darkButton = screen.getByRole('button', { name: /Dark/i });
    fireEvent.click(darkButton);

    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('should toggle theme and persist choice in localStorage', () => {
    renderWithTheme(<UserSettingsView />);

    const darkButton = screen.getByRole('button', { name: /Dark/i });
    fireEvent.click(darkButton);

    expect(localStorage.getItem('user-theme')).toBe('dark');
    expect(document.documentElement.getAttribute('data-theme')).toBe('dark');
  });
});
```

