```markdown
# Living System Specification

## User Management Service
- Handles user profiles, authentication tokens, and notification preferences.
- Endpoints: GET /api/v1/user, POST /api/v1/user/settings.

## Account gRPC Service (`AccountService`)
- Replaces legacy `AccountController`.
- **RPCs**:
  - `UpdateAccount(UpdateAccountRequest) returns (UpdateAccountResponse)`:
    - Supports partial patch updates.
    - Optional `AccountStatus` (`ACTIVE`, `INACTIVE`) using field presence (`optional` keyword or `google.protobuf.StringValue`).
    - Unset status avoids overwriting existing account state.
```

#### 2. Protobuf Definition (`account_service.proto`)

```protobuf
syntax = "proto3";

package account.v1;

enum AccountStatus {
  ACCOUNT_STATUS_UNSPECIFIED = 0;
  ACCOUNT_STATUS_ACTIVE = 1;
  ACCOUNT_STATUS_INACTIVE = 2;
}

message UpdateAccountRequest {
  string account_id = 1;
  optional AccountStatus status = 2;
  // Additional profile fields as needed
}

message UpdateAccountResponse {
  string account_id = 1;
  AccountStatus status = 2;
  bool success = 3;
}

service AccountService {
  rpc UpdateAccount (UpdateAccountRequest) returns (UpdateAccountResponse);
}
```

#### 3. Service Implementation (Example: Go / Node.js / Java pattern)

```typescript
import { sendUnaryData, ServerUnaryCall, status } from '@grpc/grpc-js';
import { 
  UpdateAccountRequest, 
  UpdateAccountResponse, 
  AccountStatus 
} from './generated/account_service_pb';
import { IAccountServiceServer } from './generated/account_service_grpc_pb';

export class AccountServiceImpl implements IAccountServiceServer {
  [name: string]: import("@grpc/grpc-js").UntypedHandleCall;

  async updateAccount(
    call: ServerUnaryCall<UpdateAccountRequest, UpdateAccountResponse>,
    callback: sendUnaryData<UpdateAccountResponse>
  ): Promise<void> {
    const { account_id } = call.request;

    if (!account_id) {
      return callback({
        code: status.INVALID_ARGUMENT,
        message: 'account_id is required',
      });
    }

    // Check optional field presence (proto3 optional)
    const hasStatus = call.request.hasStatus();
    let statusToUpdate: AccountStatus | undefined;

    if (hasStatus) {
      statusToUpdate = call.request.getStatus();
      if (statusToUpdate === AccountStatus.ACCOUNT_STATUS_UNSPECIFIED) {
        return callback({
          code: status.INVALID_ARGUMENT,
          message: 'Invalid status provided',
        });
      }
    }

    try {
      // Execute partial update repository call
      const updatedAccount = await accountRepository.patch(account_id, {
        ...(hasStatus && { status: statusToUpdate }),
      });

      const response = new UpdateAccountResponse();
      response.setAccountId(updatedAccount.id);
      response.setStatus(updatedAccount.status);
      response.setSuccess(true);

      callback(null, response);
    } catch (err) {
      callback({
        code: status.INTERNAL,
        message: (err as Error).message,
      });
    }
  }
}
```

