func (m *MockAccountRepo) Update(ctx context.Context, id string, updates service.AccountUpdates) (*service.AccountRecord, error) {
	acc, exists := m.accounts[id]
	if !exists {
		return nil, service.ErrNotFound
	}
	if updates.Status != nil {
		acc.Status = *updates.Status
	}
	if updates.DisplayName != nil {
