		accounts: map[string]*service.AccountRecord{
			"acc-1": {ID: "acc-1", DisplayName: "Alice", Status: "ACTIVE"},
		},
	}
	srv := service.NewAccountServiceServer(repo)

	t.Run("Update status to INACTIVE", func(t *testing.T) {
		req := &pb.UpdateAccountRequest{
			AccountId: "acc-1",
			Status:    pb.AccountStatus_ACCOUNT_STATUS_INACTIVE.Enum(),
		}
		resp, err := srv.UpdateAccount(context.Background(), req)
		require.NoError(t, err)
		assert.Equal(t, pb.AccountStatus_ACCOUNT_STATUS_INACTIVE, resp.Status)
		assert.Equal(t, "Alice", resp.DisplayName)
	})

	t.Run("Partial update with omitted status does not overwrite existing status", func(t *testing.T) {
		newDisplayName := "Alice In Wonderland"
		req := &pb.UpdateAccountRequest{
			AccountId:   "acc-1",
			DisplayName: &newDisplayName,
			// Status omitted (nil)
		}
		resp, err := srv.UpdateAccount(context.Background(), req)
		require.NoError(t, err)
		assert.Equal(t, pb.AccountStatus_ACCOUNT_STATUS_INACTIVE, resp.Status) // Retains previous state
		assert.Equal(t, "Alice In Wonderland", resp.DisplayName)
	})

	t.Run("Reject UNSPECIFIED status value", func(t *testing.T) {
		req := &pb.UpdateAccountRequest{
			AccountId: "acc-1",
			Status:    pb.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED.Enum(),
		}
		_, err := srv.UpdateAccount(context.Background(), req)
		require.Error(t, err)
		st, ok := status.FromError(err)
		require.True(t, ok)
