### 4.2 Step 2: Implementation

```go
// account_service.go
package service

import (
	"context"
	"errors"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	pb "github.com/org/account/v1"
)

var ErrNotFound = errors.New("account not found")

type AccountRecord struct {
	ID          string
	DisplayName string
	Status      string
	UpdatedAt   time.Time
}

type AccountUpdates struct {
	DisplayName *string
	Status      *string
}

type AccountRepository interface {
	Get(ctx context.Context, id string) (*AccountRecord, error)
	Update(ctx context.Context, id string, updates AccountUpdates) (*AccountRecord, error)
}

type AccountServiceServer struct {
	pb.UnimplementedAccountServiceServer
	repo AccountRepository
}

func NewAccountServiceServer(repo AccountRepository) *AccountServiceServer {
	return &AccountServiceServer{repo: repo}
}

func (s *AccountServiceServer) UpdateAccount(ctx context.Context, req *pb.UpdateAccountRequest) (*pb.UpdateAccountResponse, error) {
	if req.GetAccountId() == "" {
		return nil, status.Error(codes.InvalidArgument, "account_id is required")
	}

	var updates AccountUpdates

	if req.DisplayName != nil {
		updates.DisplayName = req.DisplayName
	}

	if req.Status != nil {
		switch *req.Status {
		case pb.AccountStatus_ACCOUNT_STATUS_ACTIVE:
			val := "ACTIVE"
			updates.Status = &val
		case pb.AccountStatus_ACCOUNT_STATUS_INACTIVE:
			val := "INACTIVE"
			updates.Status = &val
		case pb.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED:
			return nil, status.Error(codes.InvalidArgument, "status cannot be ACCOUNT_STATUS_UNSPECIFIED")
		default:
			return nil, status.Error(codes.InvalidArgument, "unknown account status")
		}
	}

	updatedRecord, err := s.repo.Update(ctx, req.GetAccountId(), updates)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "account with id %q not found", req.GetAccountId())
		}
		return nil, status.Errorf(codes.Internal, "failed to update account: %v", err)
	}

	var pbStatus pb.AccountStatus
	switch updatedRecord.Status {
	case "ACTIVE":
		pbStatus = pb.AccountStatus_ACCOUNT_STATUS_ACTIVE
	case "INACTIVE":
		pbStatus = pb.AccountStatus_ACCOUNT_STATUS_INACTIVE
	default:
		pbStatus = pb.AccountStatus_ACCOUNT_STATUS_UNSPECIFIED
	}

	return &pb.UpdateAccountResponse{
		AccountId:        updatedRecord.ID,
		DisplayName:      updatedRecord.DisplayName,
		Status:           pbStatus,
		UpdatedAtUnixMs:  time.Now().UnixMilli(),
	}, nil
}
```

