### 2. Implementation: `internal/service/user_service.go`

```go
package service

import (
	"context"
	"errors"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	// Replace with actual generated proto path and domain imports
	pb "your-project/gen/proto"
	"your-project/internal/domain"
)

type UserDomainService interface {
	GetByID(ctx context.Context, id string) (*domain.User, error)
	Create(ctx context.Context, user *domain.User) (*domain.User, error)
	Update(ctx context.Context, user *domain.User) (*domain.User, error)
	Delete(ctx context.Context, id string) error
}

type UserServiceServer struct {
	pb.UnimplementedUserServiceServer
	domainService UserDomainService
}

func NewUserServiceServer(ds UserDomainService) *UserServiceServer {
	return &UserServiceServer{
		domainService: ds,
	}
}

func (s *UserServiceServer) GetUser(ctx context.Context, req *pb.GetUserRequest) (*pb.GetUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user ID is required")
	}

	user, err := s.domainService.GetByID(ctx context.Context, req.GetId())
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Error(codes.NotFound, "user not found")
		}
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}

	return &pb.GetUserResponse{
		User: mapDomainToProto(user),
	}, nil
}

func (s *UserServiceServer) CreateUser(ctx context.Context, req *pb.CreateUserRequest) (*pb.CreateUserResponse, error) {
	if req.GetEmail() == "" || req.GetName() == "" {
		return nil, status.Error(codes.InvalidArgument, "email and name are required")
	}

	u := &domain.User{
		Name:  req.GetName(),
		Email: req.GetEmail(),
	}

	created, err := s.domainService.Create(ctx, u)
	if err != nil {
		if errors.Is(err, domain.ErrAlreadyExists) {
			return nil, status.Error(codes.AlreadyExists, "user with email already exists")
		}
		return nil, status.Errorf(codes.Internal, "failed to create user: %v", err)
	}

	return &pb.CreateUserResponse{
		User: mapDomainToProto(created),
	}, nil
}

func (s *UserServiceServer) UpdateUser(ctx context.Context, req *pb.UpdateUserRequest) (*pb.UpdateUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user ID is required")
	}

	u := &domain.User{
		ID:    req.GetId(),
		Name:  req.GetName(),
		Email: req.GetEmail(),
	}

	updated, err := s.domainService.Update(ctx, u)
	if err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Error(codes.NotFound, "user not found")
		}
		return nil, status.Errorf(codes.Internal, "failed to update user: %v", err)
	}

	return &pb.UpdateUserResponse{
		User: mapDomainToProto(updated),
	}, nil
}

func (s *UserServiceServer) DeleteUser(ctx context.Context, req *pb.DeleteUserRequest) (*pb.DeleteUserResponse, error) {
	if req.GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user ID is required")
	}

	if err := s.domainService.Delete(ctx, req.GetId()); err != nil {
		if errors.Is(err, domain.ErrNotFound) {
			return nil, status.Error(codes.NotFound, "user not found")
		}
		return nil, status.Errorf(codes.Internal, "failed to delete user: %v", err)
	}

	return &pb.DeleteUserResponse{Success: true}, nil
}

func mapDomainToProto(u *domain.User) *pb.User {
	if u == nil {
		return nil
	}
	return &pb.User{
		Id:    u.ID,
		Name:  u.Name,
		Email: u.Email,
	}
}
```

